contracts/CollateralVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IPriceOracle {
    function getPrice(address token) external view returns (uint256);
}

/// @title CollateralVault — vDOT deposit and health factor management
/// @notice Users deposit MockvDOT as collateral. LendingPool updates debt balances.
///         Health factor = (collateralUSD * LIQUIDATION_THRESHOLD * 1e18) / (debtUSD * 100)
///         Health factor < 1e18 → position is liquidatable
contract CollateralVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    /// @notice Loan-to-value ratio — users borrow up to 70% of collateral USD value
    uint256 public constant LTV = 70;

    /// @notice Liquidation threshold — positions liquidatable when debt/collateral > 80%
    uint256 public constant LIQUIDATION_THRESHOLD = 80;

    IERC20 public immutable vdot;
    IPriceOracle public immutable oracle;

    /// @notice Address of LendingPool — only it can set debt and seize collateral
    address public lendingPool;

    /// @notice vDOT collateral balance per user
    mapping(address => uint256) public collateralBalance;

    /// @notice HOLLAR debt balance per user (in 1e18, set by LendingPool)
    mapping(address => uint256) public debtBalance;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event LendingPoolSet(address indexed pool);

    modifier onlyLendingPool() {
        require(msg.sender == lendingPool, "Vault: only lending pool");
        _;
    }

    constructor(address _vdot, address _oracle) {
        require(_vdot != address(0), "Vault: zero vdot");
        require(_oracle != address(0), "Vault: zero oracle");
        vdot = IERC20(_vdot);
        oracle = IPriceOracle(_oracle);
    }

    /// @notice Set the LendingPool address — owner only, called once after deployment
    function setLendingPool(address pool) external onlyOwner {
        require(pool != address(0), "Vault: zero pool");
        lendingPool = pool;
        emit LendingPoolSet(pool);
    }

    /// @notice Deposit vDOT as collateral
    /// @param amount Amount of vDOT in 1e18
    function deposit(uint256 amount) external nonReentrant {
        require(amount > 0, "Vault: zero amount");
        vdot.safeTransferFrom(msg.sender, address(this), amount);
        collateralBalance[msg.sender] += amount;
        emit Deposited(msg.sender, amount);
    }

    /// @notice Withdraw vDOT collateral — reverts if withdrawal would breach LTV
    /// @param amount Amount of vDOT in 1e18
    function withdraw(uint256 amount) external nonReentrant {
        require(amount > 0, "Vault: zero amount");
        require(collateralBalance[msg.sender] >= amount, "Vault: insufficient collateral");

        uint256 newCollateral = collateralBalance[msg.sender] - amount;

        if (debtBalance[msg.sender] > 0) {
            uint256 vdotPrice = oracle.getPrice(address(vdot));
            uint256 newCollateralUSD = (newCollateral * vdotPrice) / 1e18;
            // Enforce LTV: debt <= collateral * LTV / 100
            require(
                debtBalance[msg.sender] * 100 <= newCollateralUSD * LTV,
                "Vault: below LTV after withdrawal"
            );
        }

        collateralBalance[msg.sender] = newCollateral;
        vdot.safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    /// @notice Get USD value of a user's collateral — 1e18 scaled
    /// @param user User address
    /// @return USD value of collateral
    function getCollateralValue(address user) external view returns (uint256) {
        if (collateralBalance[user] == 0) return 0;
        uint256 vdotPrice = oracle.getPrice(address(vdot));
        return (collateralBalance[user] * vdotPrice) / 1e18;
    }

    /// @notice Get health factor for a user
    ///         Returns type(uint256).max if no debt (fully healthy)
    ///         Returns < 1e18 if liquidatable
    /// @param user User address
    /// @return Health factor scaled to 1e18
    function getHealthFactor(address user) external view returns (uint256) {
        if (debtBalance[user] == 0) return type(uint256).max;
        uint256 vdotPrice = oracle.getPrice(address(vdot));
        uint256 collateralUSD = (collateralBalance[user] * vdotPrice) / 1e18;
        // healthFactor = (collateralUSD * LIQUIDATION_THRESHOLD * 1e18) / (debtUSD * 100)
        return (collateralUSD * LIQUIDATION_THRESHOLD * 1e18) / (debtBalance[user] * 100);
    }

    /// @notice Update a user's debt — called by LendingPool only
    /// @param user User address
    /// @param debt New debt amount in 1e18
    function setDebt(address user, uint256 debt) external onlyLendingPool {
        debtBalance[user] = debt;
    }

    /// @notice Seize collateral during liquidation — called by LendingPool only
    /// @param user Borrower address
    /// @param amount Amount of vDOT to seize
    /// @param recipient Address to receive the seized vDOT (liquidator)
    function seizeCollateral(address user, uint256 amount, address recipient) external onlyLendingPool {
        require(collateralBalance[user] >= amount, "Vault: insufficient collateral to seize");
        collateralBalance[user] -= amount;
        vdot.safeTransfer(recipient, amount);
    }
}

contracts/Counter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title Counter — scaffold verification contract
/// @notice Minimal counter to verify Hardhat + PolkaVM deployment pipeline
contract Counter {
    uint256 public count;

    event Incremented(address indexed caller, uint256 newCount);

    function increment() external {
        count += 1;
        emit Incremented(msg.sender, count);
    }

    function reset() external {
        count = 0;
    }
}

contracts/LendingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface ICollateralVault {
    function getCollateralValue(address user) external view returns (uint256);
    function getHealthFactor(address user) external view returns (uint256);
    function setDebt(address user, uint256 debt) external;
    function seizeCollateral(address user, uint256 amount, address recipient) external;
    function debtBalance(address user) external view returns (uint256);
    function collateralBalance(address user) external view returns (uint256);
}

interface IPriceOracle {
    function getPrice(address token) external view returns (uint256);
}

interface IMintBurn {
    function mint(address to, uint256 amount) external;
    function burn(uint256 amount) external;
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface ISolvencyVerifier {
    function verifySolvency(bytes calldata proof, uint256[] calldata publicInputs) external view returns (bool);
}

/// @title LendingPool — borrow, repay, and liquidate HOLLAR against vDOT collateral
/// @notice Stability fee accrues on every interaction via block.timestamp.
///         No cron needed — interest is lazily updated per user.
contract LendingPool is Ownable, ReentrancyGuard {
    /// @notice Stability fee in basis points — 5 bps = 0.5% per year
    uint256 public constant STABILITY_FEE = 5;
    uint256 public constant FEE_PRECISION = 10000;
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    /// @notice Liquidation bonus — liquidator receives 5% extra collateral
    uint256 public constant LIQUIDATION_BONUS = 5;
    uint256 public constant BONUS_PRECISION = 100;

    ICollateralVault public immutable vault;
    IMintBurn public immutable hollar;
    IPriceOracle public immutable oracle;
    address public immutable vdot;

    /// @notice Solvency verifier — set once, immutable after deployment
    ISolvencyVerifier public solvencyVerifier;

    /// @notice Timestamp of last interest accrual per user
    mapping(address => uint256) public lastAccrualTime;

    event Borrowed(address indexed user, uint256 hollarAmount);
    event Repaid(address indexed user, uint256 hollarAmount);
    event Liquidated(
        address indexed borrower,
        address indexed liquidator,
        uint256 debtRepaid,
        uint256 collateralSeized
    );
    event InterestAccrued(address indexed user, uint256 interest);
    event SolvencyProven(
        uint256 totalCollateral,
        uint256 totalDebt,
        uint256 timestamp
    );

    constructor(
        address _vault,
        address _hollar,
        address _oracle,
        address _vdot
    ) {
        require(_vault != address(0), "Pool: zero vault");
        require(_hollar != address(0), "Pool: zero hollar");
        require(_oracle != address(0), "Pool: zero oracle");
        require(_vdot != address(0), "Pool: zero vdot");
        vault = ICollateralVault(_vault);
        hollar = IMintBurn(_hollar);
        oracle = IPriceOracle(_oracle);
        vdot = _vdot;
    }

    /// @notice Set the solvency verifier — owner only, can only be set once
    function setSolvencyVerifier(address _verifier) external onlyOwner {
        require(address(solvencyVerifier) == address(0), "Pool: verifier already set");
        require(_verifier != address(0), "Pool: zero verifier");
        solvencyVerifier = ISolvencyVerifier(_verifier);
    }

    /// @notice Publish a ZK solvency proof — permissionless, anyone can call
    /// @param proof        Raw proof bytes from Noir/barretenberg
    /// @param publicInputs [total_collateral_value, total_debt, oracle_timestamp]
    function publishSolvencyProof(
        bytes calldata proof,
        uint256[] calldata publicInputs
    ) external {
        require(address(solvencyVerifier) != address(0), "Pool: verifier not set");
        require(publicInputs.length == 3, "Pool: wrong input count");

        require(
            solvencyVerifier.verifySolvency(proof, publicInputs),
            "Pool: invalid solvency proof"
        );

        emit SolvencyProven(publicInputs[0], publicInputs[1], publicInputs[2]);
    }

    /// @notice Accrue stability fee interest for a user
    function accrueInterest(address user) public {
        uint256 debt = vault.debtBalance(user);
        if (debt == 0) {
            lastAccrualTime[user] = block.timestamp;
            return;
        }
        uint256 last = lastAccrualTime[user];
        if (last == 0 || block.timestamp <= last) return;

        uint256 elapsed = block.timestamp - last;
        uint256 interest = (debt * STABILITY_FEE * elapsed) / (FEE_PRECISION * SECONDS_PER_YEAR);

        if (interest > 0) {
            vault.setDebt(user, debt + interest);
            emit InterestAccrued(user, interest);
        }
        lastAccrualTime[user] = block.timestamp;
    }

    /// @notice Borrow HOLLAR against deposited vDOT collateral
    function borrow(uint256 hollarAmount) external nonReentrant {
        require(hollarAmount > 0, "Pool: zero amount");
        accrueInterest(msg.sender);

        uint256 collateralUSD = vault.getCollateralValue(msg.sender);
        require(collateralUSD > 0, "Pool: no collateral");

        uint256 currentDebt = vault.debtBalance(msg.sender);
        uint256 newDebt = currentDebt + hollarAmount;

        require(newDebt * 100 <= collateralUSD * 70, "Pool: exceeds LTV");

        vault.setDebt(msg.sender, newDebt);
        if (lastAccrualTime[msg.sender] == 0) {
            lastAccrualTime[msg.sender] = block.timestamp;
        }

        hollar.mint(msg.sender, hollarAmount);
        emit Borrowed(msg.sender, hollarAmount);
    }

    /// @notice Repay HOLLAR debt
    function repay(uint256 hollarAmount) external nonReentrant {
        require(hollarAmount > 0, "Pool: zero amount");
        accrueInterest(msg.sender);

        uint256 debt = vault.debtBalance(msg.sender);
        require(debt > 0, "Pool: no debt");

        uint256 repayAmount = hollarAmount > debt ? debt : hollarAmount;

        hollar.transferFrom(msg.sender, address(this), repayAmount);
        hollar.burn(repayAmount);

        vault.setDebt(msg.sender, debt - repayAmount);
        lastAccrualTime[msg.sender] = block.timestamp;

        emit Repaid(msg.sender, repayAmount);
    }

    /// @notice Liquidate an undercollateralized position
    function liquidate(address borrower) external nonReentrant {
        accrueInterest(borrower);

        uint256 healthFactor = vault.getHealthFactor(borrower);
        require(healthFactor < 1e18, "Pool: position healthy");

        uint256 debt = vault.debtBalance(borrower);
        require(debt > 0, "Pool: no debt");

        hollar.transferFrom(msg.sender, address(this), debt);
        hollar.burn(debt);

        uint256 vdotPrice = oracle.getPrice(vdot);
        uint256 debtInVdot = (debt * 1e18) / vdotPrice;
        uint256 collateralToSeize = debtInVdot + (debtInVdot * LIQUIDATION_BONUS) / BONUS_PRECISION;

        uint256 actualCollateral = vault.collateralBalance(borrower);
        if (collateralToSeize > actualCollateral) {
            collateralToSeize = actualCollateral;
        }

        vault.setDebt(borrower, 0);
        // Vault sends vDOT directly to liquidator — no IERC20 needed in this contract
        vault.seizeCollateral(borrower, collateralToSeize, msg.sender);

        emit Liquidated(borrower, msg.sender, debt, collateralToSeize);
    }
}

contracts/MockHOLLAR.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title MockHOLLAR — testnet mock of Hydration HOLLAR stablecoin
/// @notice USD-pegged stablecoin mock for Westend Asset Hub testing
/// @dev mint() is public for testnet faucet purposes; burn() via ERC20Burnable for LendingPool
contract MockHOLLAR is ERC20, ERC20Burnable, Ownable {
    uint8 private constant _DECIMALS = 18;

    constructor() ERC20("Mock HOLLAR", "HOLLAR") {}

